const root = repoRoot();
const configPath = join(root, ".github/holdpoint/generated/checks.immutable.json");
if (!existsSync(configPath)) process.exit(0);

let cfg = {};
try { cfg = JSON.parse(readFileSync(configPath, "utf8")); } catch { process.exit(0); }

const parts = [];
